import {hearButton} from './play-media.mjs';
import {collectionInputStatus,collectionView,startCollection,recoverCollection,editCollection,supportCollection,checkCollection,keepCollection} from './count-collection-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=['collect','table','chart','read'],titles={collect:'Make our collection',table:'Make our table',chart:'Draw our bars',read:'Read our chart'};
const entryNotice=input=>({blank:'Not recorded yet. Blank is not zero.',invalid:'Use a whole number from 0 to 12, or leave blank.',ready:'A whole-count draft is entered.'}[collectionInputStatus(input)]);
const turnIntro=w=>w.page==='collect'?'What will be in your collection? Each picture stands for one imaginary button.':w.page==='table'?'Record the collection in a table. Blank table boxes are not zero.':w.page==='chart'?'Make bars for the collection, then compare the drafts.':'Read the bars you made. A reading can fit your chart even when the chart differs from the collection.';
function narration(w){
 const prefix=titles[w.page]+'. '+turnIntro(w)+' ';
 if(w.page==='collect')return prefix+w.source.categories.map(c=>`${c.label}: ${c.count}.`).join(' ');
 if(w.page==='table')return prefix+'Open Look at our collection to count its pictures. '+w.source.categories.map(c=>`${c.label} table entry: ${w.table[c.id].trim()||'not recorded yet'}.`).join(' ');
 const bars=w.source.categories.map(c=>`${c.label} bar: ${w.bars[c.id]}.`).join(' ');
 if(w.page==='chart')return prefix+bars+` Axis labels count by ${w.scale===1?'ones':'twos'}.`;
 const pair=w.source.categories.slice(0,2);return prefix+bars+(pair.length<2?' This version has one category. You can keep its chart, or start a separate collection to compare categories.':` In your chart, are there more ${pair[0].label.toLowerCase()}, more ${pair[1].label.toLowerCase()}, or the same number? How many more, or 0 if the bars are equal? Your difference entry is ${w.response.difference.trim()||'not recorded yet'}.`);
}
const positions=[[22,25],[64,15],[111,31],[151,16],[36,63],[85,57],[140,68],[20,98],[65,102],[114,95],[160,103],[165,49]];
function shape(c,x,y){const common='fill="#ebd091" stroke="#335c4a" stroke-width="2"';return c.shape==='circle'?`<circle cx="${x}" cy="${y}" r="8" ${common}/><circle cx="${x}" cy="${y}" r="2" fill="#335c4a"/>`:c.shape==='square'?`<rect x="${x-8}" y="${y-8}" width="16" height="16" rx="2" ${common}/><path d="M${x-4} ${y}h8" stroke="#335c4a"/>`:`<path d="M${x} ${y-9}l9 17h-18Z" ${common}/><circle cx="${x}" cy="${y+2}" r="2" fill="#335c4a"/>`;}
function pictures(s,editable=false){return `<div class="collection-categories">${s.categories.map(c=>`<article class="collection-category"><h3>${esc(c.label)}</h3><svg class="collection-pictures" viewBox="0 0 185 120" role="img" aria-label="${esc(`${c.count} ${c.label}. Each picture stands for one button.`)}">${positions.slice(0,c.count).map(([x,y])=>`<g class="collection-token">${shape(c,x,y)}</g>`).join('')}</svg><p><strong>${c.count}</strong> ${esc(c.label.toLowerCase())}</p>${editable?`<div class="collection-adjust"><button class="secondary" data-collection-count="${esc(c.id)}" data-delta="-1" ${c.count===0?'disabled':''} aria-label="Remove one ${esc(c.label.toLowerCase())}">−</button><button class="secondary" data-collection-count="${esc(c.id)}" data-delta="1" ${c.count===12?'disabled':''} aria-label="Add one ${esc(c.label.toLowerCase())}">+</button></div>`:''}</article>`).join('')}</div>`;}
function chart(s,bars,scale){const height=s.categories.length*42+44,ticks=Array.from({length:12/scale+1},(_,i)=>i*scale);return `<div class="collection-chart"><p><strong>Our button chart</strong> · Number of buttons</p><svg viewBox="0 0 300 ${height}" role="img" aria-label="${esc(s.categories.map((c,i)=>`Category ${i+1}, ${c.label}: ${bars[c.id]} buttons`).join('. '))}">${ticks.map(n=>`<path d="M${38+n*20} 8V${height-28}" stroke="#d3ded7"/><text x="${38+n*20}" y="${height-8}" text-anchor="middle">${n}</text>`).join('')}<path d="M38 8V${height-28}H278" fill="none" stroke="#335c4a" stroke-width="2"/>${s.categories.map((c,i)=>`<text x="24" y="${i*42+32}" text-anchor="middle">${i+1}</text><rect data-collection-bar="${esc(c.id)}" data-value="${bars[c.id]}" x="38" y="${i*42+12}" width="${bars[c.id]*20}" height="26" fill="#8bb6a2" stroke="#335c4a"/><text x="${44+bars[c.id]*20}" y="${i*42+30}">${bars[c.id]}</text>`).join('')}</svg><ol>${s.categories.map(c=>`<li>${esc(c.label)}</li>`).join('')}</ol><p class="tiny">All bars start at 0. Each bar value counts buttons; changing tick labels does not change its amount.</p></div>`;}
function savedVersion(s){return `<p>${esc(s.source.title)}</p><ul>${s.source.categories.map(c=>`<li>${esc(c.label)}: collection ${c.count}; table ${esc(s.table[c.id]||'(blank)')}; bar ${s.bars[c.id]}.</li>`).join('')}</ul><p class="tiny">Support recorded: ${esc(s.support.join(', ')||'none')}. Pictured practice; no level is inferred.</p>`;}
export const collectionEntry=()=>'<section class="resume-strip collection-entry"><div><h2>My Count Collection</h2><p>Make a pretend button collection for the mending table, then leave a chart for another helper.</p><a class="secondary" href="#living/collection">Make our own collection</a></div></section>';
export function collectionPage(state){
 const v=collectionView(state),back='<a class="back" href="#living/notebook"><span aria-hidden="true">←</span> Back to Field Notebook</a>',status='<p id="collection-status" role="status" tabindex="-1"></p>';
 if(v.status!=='ready')return `<section class="collection-sheet">${back}<h1 id="collection-title" tabindex="-1">My Count Collection</h1><p>${v.status==='missing'?'The mending table is getting ready for the lantern walk. Make a pretend button collection, then leave a chart so another helper can see what is here.':'This earlier collection cannot be opened safely. It remains in your notes download; the other games stay open.'}</p><button class="primary" ${v.status==='missing'?'data-collection-start':'data-collection-recover'}>${v.status==='missing'?'Start our collection':'Start a separate collection'}</button>${status}<a class="secondary" href="#notes">Grown-up notes</a></section>`;
 const w=v.work,s=w.source,pair=s.categories.slice(0,2),index=pages.indexOf(w.page),hear=narration(w);
 const source=w.page==='collect'?pictures(s,true):`<details class="collection-source"><summary>Look at our collection</summary>${pictures(s)}</details>`;
 const table=`<div class="collection-table">${s.categories.map(c=>`<label>${esc(c.label)} <input data-collection-table="${esc(c.id)}" type="text" inputmode="decimal" maxlength="16" autocomplete="off" value="${esc(w.table[c.id])}" aria-label="Table count for ${esc(c.label)}" aria-describedby="collection-entry-${esc(c.id)}"><span class="tiny" id="collection-entry-${esc(c.id)}">${esc(entryNotice(w.table[c.id]))}</span></label>`).join('')}</div>`;
 const bars=`<div class="collection-bar-controls">${s.categories.map((c,i)=>`<div><span>${i+1}. ${esc(c.label)}: <strong>${w.bars[c.id]}</strong></span><button class="secondary" data-collection-bar-edit="${esc(c.id)}" data-delta="-1" ${w.bars[c.id]===0?'disabled':''} aria-label="Shorten ${esc(c.label)} bar by one">−</button><button class="secondary" data-collection-bar-edit="${esc(c.id)}" data-delta="1" ${w.bars[c.id]===12?'disabled':''} aria-label="Lengthen ${esc(c.label)} bar by one">+</button></div>`).join('')}</div>`;
 const reading=pair.length<2?'<p>This version has one category. You can keep its chart, or start a separate collection to compare categories.</p>':`<fieldset><legend>In your chart, are there more ${esc(pair[0].label.toLowerCase())}, more ${esc(pair[1].label.toLowerCase())}, or the same number?</legend><div class="collection-reading">${[['first',pair[0].label],['same','Same number'],['second',pair[1].label]].map(([id,label])=>`<button class="method ${w.response.choice===id?'selected':''}" data-collection-choice="${id}" aria-pressed="${w.response.choice===id}">${esc(label)}</button>`).join('')}</div></fieldset><label>How many more, or 0 if the bars are equal? <input id="collection-difference" type="text" inputmode="decimal" maxlength="16" autocomplete="off" value="${esc(w.response.difference)}"></label><button class="primary" data-collection-check="reading">Read this chart</button>`;
 return `<section class="collection-sheet" data-collection-root>${back}<p class="tiny">My Count Collection · ${index+1} of 4</p><h1 id="collection-title" tabindex="-1">${titles[w.page]}</h1><p>${turnIntro(w)}</p>${hearButton(hear,'Hear this turn')}${status}${source}${w.page==='table'?table:w.page==='chart'?`<details><summary>Look at our table draft</summary>${table}</details>${chart(s,w.bars,w.scale)}<fieldset><legend>Axis tick labels</legend>${[1,2].map(n=>`<button class="method ${w.scale===n?'selected':''}" data-collection-scale="${n}" aria-pressed="${w.scale===n}">Count by ${n===1?'ones':'twos'}</button>`).join('')}</fieldset>${bars}<button class="primary" data-collection-check="representation">Check our representation</button>`:w.page==='read'?chart(s,w.bars,w.scale)+reading:''}${v.feedback?`<p id="collection-feedback" class="feedback" tabindex="-1">${esc(v.feedback.feedback)}</p>`:''}<details class="collection-help"><summary>Help and working together</summary><p>One picture stands for one button. The table records the collection. Each bar starts at zero. A chart can be read correctly even if it does not match its source. You can change a draft without changing an earlier check.</p><button class="secondary" data-collection-together>We worked together</button></details><div class="collection-pages">${index>0?`<button class="secondary" data-collection-page="${pages[index-1]}">Previous</button>`:''}${index<pages.length-1?`<button class="primary" data-collection-page="${pages[index+1]}">Next: ${titles[pages[index+1]].toLowerCase()}</button>`:''}</div><button class="secondary" data-collection-keep ${v.keptUnreadable?'disabled':''}>${w.kept===null?'Keep this version':'Replace our kept version'}</button>${v.keptUnreadable?'<p>Your earlier kept version is unreadable and remains in your download. Start a separate collection to keep another version.</p>':v.kept?`<details><summary>Our kept version</summary>${savedVersion(v.kept.snapshot)}${v.kept.check?`<p>${esc(v.kept.check.feedback)}</p>`:''}</details>`:''}<details><summary>Latest four checks (${Math.min(4,v.readable.length)})</summary><p class="tiny">Earlier versions; later drafts do not change them. New readable checks replace the oldest in this recent window.</p>${v.readable.slice(-4).map(c=>`<article class="collection-earlier"><h3>Earlier check ${c.id}</h3>${savedVersion(c.snapshot)}<p>${esc(c.feedback)}</p></article>`).join('')}${v.unreadable.length?`<p>${v.unreadable.length} earlier check(s) are unreadable and remain in your notes download.</p>`:''}</details><details><summary>Grown-ups: source and practice</summary><p>This is a fictional collection made with screen buttons, not a survey or verified observation. Source counts, table drafts and chart readings stay separate. Help, narration requests and working together remain reported context. No level or science attainment is inferred. Kept work and the latest four checks stay local with existing save/export controls.</p><a href="#notes">Grown-up notes</a><button class="text-button" data-collection-recover>Start a separate collection</button></details></section>`;
}
export function collectionNotes(state){const v=collectionView(state);if(v.status==='missing')return '';if(v.status==='recovery')return '<section><h2>My Count Collection</h2><p>Unreadable saved collection retained in the download.</p></section>';return `<details class="panel"><summary>My Count Collection</summary>${savedVersion(v.work)}${v.readable.slice(-4).map(c=>`<article><h3>Earlier check ${c.id}</h3>${savedVersion(c.snapshot)}<p>${esc(c.feedback)}</p></article>`).join('')}${v.kept?`<h3>Kept version</h3>${savedVersion(v.kept.snapshot)}`:''}${v.unreadable.length||v.keptUnreadable?'<p>Some earlier work is unreadable; raw data remains in the download.</p>':''}</details>`;}
export function bindCollection(state,{save,render,focus,canExport}){
 const root=document.querySelector('.collection-sheet');if(!root)return;
 const notice=text=>{const n=document.querySelector('#collection-status');if(n){n.textContent=text;focus('#collection-status');}};
 const run=(action,target,message)=>{if(!action()){notice('This version could not change safely. Download your notes, or start a separate explorer if the notebook is full.');return false;}save();render();if(message)notice(message);else if(target){const b=document.querySelector(target);if(b?.disabled&&b.dataset.delta){const attr=b.dataset.collectionCount?'collection-count':'collection-bar-edit';focus(`[data-${attr}="${b.getAttribute(`data-${attr}`)}"][data-delta="${-Number(b.dataset.delta)}"]`);}else focus(target);}return true;};
 const confirm=(title,action,retainsRoot=false)=>{const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${title}</h2><p>${retainsRoot?'A separate collection retains the entire previous collection in your download. Download your notes first if you want another copy.':'The earlier kept version will be replaced. Download your notes first if you want to keep that version too.'}</p><button class="secondary" data-collection-cancel>Keep this page</button><button class="primary" data-collection-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-collection-cancel]').onclick=()=>{d.close();d.remove();};d.querySelector('[data-collection-confirm]').onclick=()=>{d.close();d.remove();run(action,'#collection-title','Your change is kept.');};d.addEventListener('cancel',()=>d.remove());};
 root.querySelector('[data-collection-start]')?.addEventListener('click',()=>run(()=>startCollection(state,canExport),'#collection-title'));
 root.querySelectorAll('[data-collection-recover]').forEach(b=>b.onclick=()=>confirm('Start a separate collection?',()=>recoverCollection(state,canExport),true));
 root.querySelectorAll('[data-collection-page]').forEach(b=>b.onclick=()=>run(()=>editCollection(state,'page',null,b.dataset.collectionPage),'#collection-title'));
 for(const [selector,kind,key] of [['[data-collection-count]','count','collectionCount'],['[data-collection-bar-edit]','bar','collectionBarEdit']])root.querySelectorAll(selector).forEach(b=>b.onclick=()=>run(()=>editCollection(state,kind,b.dataset[key],Number(b.dataset.delta)),`${selector}[data-${kind==='count'?'collection-count':'collection-bar-edit'}="${b.dataset[key]}"][data-delta="${b.dataset.delta}"]`));
 root.querySelectorAll('[data-collection-table]').forEach(input=>input.oninput=()=>{if(editCollection(state,'table',input.dataset.collectionTable,input.value)){save();const note=document.getElementById(`collection-entry-${input.dataset.collectionTable}`);if(note)note.textContent=entryNotice(input.value);document.querySelector('#collection-feedback')?.remove();}});
 root.querySelector('#collection-difference')?.addEventListener('input',e=>{if(editCollection(state,'difference',null,e.target.value)){save();document.querySelector('#collection-feedback')?.remove();}});
 root.querySelectorAll('[data-collection-scale]').forEach(b=>b.onclick=()=>run(()=>editCollection(state,'scale',null,Number(b.dataset.collectionScale)),`[data-collection-scale="${b.dataset.collectionScale}"]`));
 root.querySelectorAll('[data-collection-choice]').forEach(b=>b.onclick=()=>run(()=>editCollection(state,'choice',null,b.dataset.collectionChoice),`[data-collection-choice="${b.dataset.collectionChoice}"]`));
 root.querySelectorAll('[data-collection-check]').forEach(b=>b.onclick=()=>run(()=>checkCollection(state,b.dataset.collectionCheck,canExport),'#collection-feedback'));
 root.querySelector('[data-collection-keep]')?.addEventListener('click',()=>{const v=collectionView(state);if(v.keptUnreadable){notice('Your earlier kept version stays in the download. Start a separate collection to keep another version.');return;}if(v.work.kept!==null)confirm('Replace our kept version?',()=>keepCollection(state,true,canExport));else run(()=>keepCollection(state,false,canExport),null,'This version is kept.');});
 root.querySelector('.collection-help')?.addEventListener('toggle',e=>{if(e.target.open&&supportCollection(state,'help'))save();});
 root.querySelector('[data-collection-together]')?.addEventListener('click',()=>{if(supportCollection(state,'together')){save();notice('Working together is recorded.');}});
 root.querySelector('[data-speak]')?.addEventListener('click',e=>{const v=collectionView(state);if(v.status==='ready')e.currentTarget.dataset.speak=narration(v.work);if(supportCollection(state,'narrationRequested'))save();});
}
